(6076595, 894690, 114225, '<td valign="top">Very nice scene. Just enought of the sky to give context to the photo. Great colors, clarity, and use of leading lines.</td>', 'Very nice scene. Just enought of the sky to give context to the photo. Great colors, clarity, and use of leading lines.', '2010-07-02 00:21:33.000000', NULL, 1),
(6076596, 893992, 114225, '<td valign="top">Good capture of the fun of the moment. This is a hard scene to expose correctly, but when done, gives the photo that extra pop it needs. That would be my suggestion here, is to try to keep the girl exposed properly, while not blowing out the sky.</td>', 'Good capture of the fun of the moment. This is a hard scene to expose correctly, but when done, gives the photo that extra pop it needs. That would be my suggestion here, is to try to keep the girl exposed properly, while not blowing out the sky.', '2010-07-02 00:22:38.000000', NULL, 1),
(6076597, 893964, 73056, '<td valign="top">I see the master of perspective, framing, clarity and cropping is at it again. Awesome shot and title.</td>', 'I see the master of perspective, framing, clarity and cropping is at it again. Awesome shot and title.', '2010-07-02 00:23:04.000000', NULL, 1),
(6076598, 894787, 114225, '<td valign="top">Awww, very cute! I love the softness and warm color cast to this photo.</td>', 'Awww, very cute! I love the softness and warm color cast to this photo.', '2010-07-02 00:23:13.000000', NULL, 1),
