(6076647, 892003, 114225, '<td valign="top">Nice timing with the sun shining through at just the right moment. I like the B&amp;W, but the sharpening seems a little bit too much.</td>', 'Nice timing with the sun shining through at just the right moment. I like the B&W, but the sharpening seems a little bit too much.', '2010-07-02 00:46:58.000000', NULL, 1),
(6076649, 893455, 114225, '<td valign="top">Cute fox! The lighting really works here to bring out the details in his fur/eye. The background is a bit distracting, and the photo would have been much better without it.</td>', 'Cute fox! The lighting really works here to bring out the details in his fur/eye. The background is a bit distracting, and the photo would have been much better without it.', '2010-07-02 00:48:36.000000', NULL, 1),
