(6080229, 894743, 75713, '<td valign="top">So adorable!  Well photographed too but it''s the emotion that this shot triggers that make it so special that it could have been blown out and still moved me.</td>', 'So adorable!  Well photographed too but it''s the emotion that this shot triggers that make it so special that it could have been blown out and still moved me.', '2010-07-04 23:08:48.000000', NULL, 1),
(6080231, 894588, 75713, '<td valign="top">Just a great capture - there at the right moment with the skill to catch it.</td>', 'Just a great capture - there at the right moment with the skill to catch it.', '2010-07-04 23:09:41.000000', NULL, 1),
(6080233, 894627, 75713, '<td valign="top">Breath taking in it''s simple beauty - well photographed and pped.</td>', 'Breath taking in it''s simple beauty - well photographed and pped.', '2010-07-04 23:11:45.000000', NULL, 1),
(6080235, 893846, 75713, '<td valign="top">Wouldn''t I love to get this close to such a magnificent eagle.  Great detail in the feathers and fantastic catching the light in it''s eye too.</td>', 'Wouldn''t I love to get this close to such a magnificent eagle.  Great detail in the feathers and fantastic catching the light in it''s eye too.', '2010-07-04 23:14:15.000000', NULL, 1),
(6080240, 893562, 83313, '<td valign="top">Kind of soft and a bit short on oomph somehow. Not a lot of detail showing in the bee. I think this may have been tough light for this kind of shot.</td>', 'Kind of soft and a bit short on oomph somehow. Not a lot of detail showing in the bee. I think this may have been tough light for this kind of shot.', '2010-07-04 23:21:10.000000', NULL, 1),
(6080246, 894765, 18367, '<td valign="top">The title alone got you an extra point.  Very nice image too.  Good luck in the challenge.</td>', 'The title alone got you an extra point.  Very nice image too.  Good luck in the challenge.', '2010-07-04 23:28:12.000000', NULL, 1),
(6080247, 893415, 83313, '<td valign="top">I like the semi-abstract view. I''m not quite sure from this partial view what plane this is.</td>', 'I like the semi-abstract view. I''m not quite sure from this partial view what plane this is.', '2010-07-04 23:32:12.000000', NULL, 1),
(6080248, 893554, 83313, '<td valign="top">Nice. Looks like something from a band shoot. I''m betting the "border patrol" will have some problems with this.</td>', 'Nice. Looks like something from a band shoot. I''m betting the "border patrol" will have some problems with this.', '2010-07-04 23:33:53.000000', NULL, 1),
(6080253, 894765, 83313, '<td valign="top">Grog can help find lost cow. Grog see many cows <a href="//www.dpchallenge.com/challenge_results.php?CHALLENGE_ID=1231" rel="nofollow" target="_blank">over here</a>.<br/> <br/>Grog is great finder-of-beasts. You thank Grog and mark comment helpful, or Grog will send Thag to visit with gift of tree bark casserole.<br/><br/><i>Message edited by author 2010-07-08 00:54:19.</i></td>', 'Grog can help find lost cow. Grog see many cows over here. Grog is great finder-of-beasts. You thank Grog and mark comment helpful, or Grog will send Thag to visit with gift of tree bark casserole.', '2010-07-04 23:44:20.000000', '2010-07-08 01:54:19.000000', 1),
(6080256, 891978, 83313, '<td valign="top">Is a garage door therapeutic for the lower back? I''ll have to give it a try.</td>', 'Is a garage door therapeutic for the lower back? I''ll have to give it a try.', '2010-07-04 23:47:21.000000', NULL, 1),
(6080257, 892748, 24454, '<td valign="top">Ohmy!  I am in total awe!  I have very few favorites in this challenge, but I think this is my favorite of them all!  Can I give it a 20?  I wish I could!</td>', 'Ohmy!  I am in total awe!  I have very few favorites in this challenge, but I think this is my favorite of them all!  Can I give it a 20?  I wish I could!', '2010-07-04 23:48:39.000000', NULL, 1),
(6080259, 894561, 83313, '<td valign="top">Thanks, I feel secure and validated as an individual now. Just a fun shot, and something a bit different!</td>', 'Thanks, I feel secure and validated as an individual now. Just a fun shot, and something a bit different!', '2010-07-04 23:51:13.000000', NULL, 1),
(6080820, 893521, 93421, '<td valign="top">I like the idea behind this image.  Personally I would like the model''s hair off her chest and her head leaning backward</td>', 'I like the idea behind this image.  Personally I would like the model''s hair off her chest and her head leaning backward', '2010-07-05 09:33:52.000000', NULL, 1),
