(6080921, 893566, 102581, '<td valign="top">Very cool shot~</td>', 'Very cool shot~', '2010-07-05 11:42:13.000000', NULL, 1),
(6080922, 891183, 102581, '<td valign="top">fantastic photo!</td>', 'fantastic photo!', '2010-07-05 11:42:20.000000', NULL, 1),
(6080923, 893939, 102581, '<td valign="top">Badass shot!  I really like it!</td>', 'Badass shot!  I really like it!', '2010-07-05 11:42:32.000000', NULL, 1),
(6080924, 894541, 102581, '<td valign="top">Fantastic!</td>', 'Fantastic!', '2010-07-05 11:42:33.000000', NULL, 1),
