(6080927, 894536, 102581, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2010-07-05 11:42:47.000000', NULL, 1),
(6080928, 894567, 102581, '<td valign="top">Great photo, it is very calming!</td>', 'Great photo, it is very calming!', '2010-07-05 11:42:52.000000', NULL, 1),
(6080929, 891788, 102581, '<td valign="top">Great shot, love the dramatic sky...</td>', 'Great shot, love the dramatic sky...', '2010-07-05 11:43:04.000000', NULL, 1),
(6080930, 893521, 102581, '<td valign="top">I may be in love here...</td>', 'I may be in love here...', '2010-07-05 11:43:08.000000', NULL, 1),
(6080931, 894846, 102581, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2010-07-05 11:43:17.000000', NULL, 1),
(6080932, 892923, 102581, '<td valign="top">Cool shot, but it looks a little over processed to me.  Good though.</td>', 'Cool shot, but it looks a little over processed to me.  Good though.', '2010-07-05 11:44:17.000000', NULL, 1),
(6080933, 892844, 102581, '<td valign="top">Cool shot!  a little blown out in the center, but very good over all.</td>', 'Cool shot!  a little blown out in the center, but very good over all.', '2010-07-05 11:44:22.000000', NULL, 1),
(6080934, 890635, 102581, '<td valign="top">I''m a sucker for night time photography.  I really like this photograph. Careful on the saturation...</td>', 'I''m a sucker for night time photography.  I really like this photograph. Careful on the saturation...', '2010-07-05 11:44:24.000000', NULL, 1),
(6080936, 893604, 102581, '<td valign="top">Me-Ow!</td>', 'Me-Ow!', '2010-07-05 11:45:54.000000', NULL, 1),
(6080950, 890797, 23484, '<td valign="top">I like the selective desat and nice angle.</td>', 'I like the selective desat and nice angle.', '2010-07-05 12:00:04.000000', NULL, 1),
(6080951, 892266, 23484, '<td valign="top">Great composition and B&amp;W conversion.</td>', 'Great composition and B&W conversion.', '2010-07-05 12:00:25.000000', NULL, 1),
(6080952, 894675, 23484, '<td valign="top">Nice job on the motion panning.</td>', 'Nice job on the motion panning.', '2010-07-05 12:00:49.000000', NULL, 1),
(6080953, 893461, 23484, '<td valign="top">Very nice symmetry and great point of view.</td>', 'Very nice symmetry and great point of view.', '2010-07-05 12:02:16.000000', NULL, 1),
(6080955, 893398, 23484, '<td valign="top">The title says it all.</td>', 'The title says it all.', '2010-07-05 12:02:42.000000', NULL, 1),
(6080956, 893534, 23484, '<td valign="top">I don''t know how you did that but it''s pretty cool.</td>', 'I don''t know how you did that but it''s pretty cool.', '2010-07-05 12:03:55.000000', NULL, 1),
(6080958, 894645, 23484, '<td valign="top">Beautiful shot and the color tone is gorgeous.</td>', 'Beautiful shot and the color tone is gorgeous.', '2010-07-05 12:04:12.000000', NULL, 1),
(6081314, 894650, 61552, '<td valign="top">a little heavy on the color saturation.</td>', 'a little heavy on the color saturation.', '2010-07-05 17:23:58.000000', NULL, 1),
(6081322, 889390, 117474, '<td valign="top">This photograph is superb. Really really excellent. <br/>There''s a hint of her eyes. That''s the only thing I''d change in it -- show more eye. <br/>If I could vote in this challenge 9 or 10 for sure.</td>', 'This photograph is superb. Really really excellent. There''s a hint of her eyes. That''s the only thing I''d change in it -- show more eye. If I could vote in this challenge 9 or 10 for sure.', '2010-07-05 17:26:55.000000', NULL, 1),
(6081351, 894516, 117474, '<td valign="top">That''s a superb shot. It took me aback when I first saw it. <br/>I love the colours, the blurring, the reflections, the eyes and the absolute sense of power that''s portrayed over the frog. If I could have voted I would have given 9/10.<br/>The only thing I don''t like is the capitalisation of every word in the title, but that''s absolutely a personal thing.</td>', 'That''s a superb shot. It took me aback when I first saw it. I love the colours, the blurring, the reflections, the eyes and the absolute sense of power that''s portrayed over the frog. If I could have voted I would have given 9/10.The only thing I don''t like is the capitalisation of every word in the title, but that''s absolutely a personal thing.', '2010-07-05 17:43:32.000000', NULL, 1),
(6081382, 893803, 102315, '<td valign="top">I''m drawn to those eyes! Amazing work.</td>', 'I''m drawn to those eyes! Amazing work.', '2010-07-05 18:35:52.000000', NULL, 1),
(6081440, 894593, 40391, '<td valign="top">This is a fantistic photo and one of my picks for the challenge! The details, lighting, colour and OOF BG are spot on.  I gave this a 9 and the only reason it wasn''t a 10 was the reflection in it''s eye. Lovely, well done!</td>', 'This is a fantistic photo and one of my picks for the challenge! The details, lighting, colour and OOF BG are spot on.  I gave this a 9 and the only reason it wasn''t a 10 was the reflection in it''s eye. Lovely, well done!', '2010-07-05 19:41:00.000000', NULL, 1),
(6081445, 890529, 40391, '<td valign="top">I don''t know if the exposure obtained will be to every DPCers liking but I feel it''s perfect.  Of the 338 submissions this is my favorite (and is added as one of my favs). A photo that tells a story is special but for me this is an entire novel!  I originally gave this a 9 but on my second viewing I''m bumbing it to my only 10 of the challenge.  I would not be surprised if this doesn''t ribbon but dissapointed if not in the top 10.  This should be in a gallery where great art is hung.  Well done!</td>', 'I don''t know if the exposure obtained will be to every DPCers liking but I feel it''s perfect.  Of the 338 submissions this is my favorite (and is added as one of my favs). A photo that tells a story is special but for me this is an entire novel!  I originally gave this a 9 but on my second viewing I''m bumbing it to my only 10 of the challenge.  I would not be surprised if this doesn''t ribbon but dissapointed if not in the top 10.  This should be in a gallery where great art is hung.  Well done!', '2010-07-05 19:49:50.000000', NULL, 1),
(6081460, 894516, 40391, '<td valign="top">What a fantasic capture! Love the title too.  The photo is technical excellent too.  This photo has so much comercial potential.  I expect to see this on the front page. Well done - 9</td>', 'What a fantasic capture! Love the title too.  The photo is technical excellent too.  This photo has so much comercial potential.  I expect to see this on the front page. Well done - 9', '2010-07-05 19:57:18.000000', NULL, 1),
(6081474, 894459, 40391, '<td valign="top">I feel the bridge is too under exposed.  There wasn''t a lot of colour in the photo so maybe changing it to black &amp; white and boosting the contrast may have been better (hard to say without really trying it and maybe you had).  However, what I really feel this shot needs is to be taken close from the ground (at least below the railings) to give it a more interesting perspective and to remove the snap shot feel of the photo. 3.</td>', 'I feel the bridge is too under exposed.  There wasn''t a lot of colour in the photo so maybe changing it to black & white and boosting the contrast may have been better (hard to say without really trying it and maybe you had).  However, what I really feel this shot needs is to be taken close from the ground (at least below the railings) to give it a more interesting perspective and to remove the snap shot feel of the photo. 3.', '2010-07-05 20:03:45.000000', NULL, 1),
(6081481, 894792, 40391, '<td valign="top">Nice choice of subject, however, I feel the PP has been overdone. I''m sure this will have its audience just as it is something that you like to do. My tastes is consistantly changing (growing?) and this type of processing may really appeal to me one day. But for today this got a 3 from me.</td>', 'Nice choice of subject, however, I feel the PP has been overdone. I''m sure this will have its audience just as it is something that you like to do. My tastes is consistantly changing (growing?) and this type of processing may really appeal to me one day. But for today this got a 3 from me.', '2010-07-05 20:08:22.000000', NULL, 1),
(6081485, 893520, 114225, '<td valign="top">Good use of background to get a nice cat portrait. Good clarity in the face/eyes, including the eye catch lights.</td>', 'Good use of background to get a nice cat portrait. Good clarity in the face/eyes, including the eye catch lights.', '2010-07-05 20:11:18.000000', NULL, 1),
(6081486, 892968, 40391, '<td valign="top">This is not a bad capture but I feel it could have been so much better. I''ve never seen this type of windmill before.  However, I''m sure I won''t be the only one to point this out (said that before and was proven wrong) but not have the horizon strait really hurts the shot. A 3 from me.</td>', 'This is not a bad capture but I feel it could have been so much better. I''ve never seen this type of windmill before.  However, I''m sure I won''t be the only one to point this out (said that before and was proven wrong) but not have the horizon strait really hurts the shot. A 3 from me.', '2010-07-05 20:11:46.000000', NULL, 1),
(6081489, 888077, 114225, '<td valign="top">Much different setup than is normally shown with cala-lilly shots. I really enjoy the lighting and textures.</td>', 'Much different setup than is normally shown with cala-lilly shots. I really enjoy the lighting and textures.', '2010-07-05 20:12:29.000000', NULL, 1),
(6081492, 893265, 114225, '<td valign="top">Great colors and reflections. It''s interesting how the area of sun doesn''t look to have any fog, but the rest of the scene does. Was that post processing or a trick of light?</td>', 'Great colors and reflections. It''s interesting how the area of sun doesn''t look to have any fog, but the rest of the scene does. Was that post processing or a trick of light?', '2010-07-05 20:13:48.000000', NULL, 1),
(6081493, 894819, 114225, '<td valign="top">Great shot. Fantastic clarity from the stars to the tree in the water. Having the tree really gives the viewer a sense for how big the scene is.</td>', 'Great shot. Fantastic clarity from the stars to the tree in the water. Having the tree really gives the viewer a sense for how big the scene is.', '2010-07-05 20:14:33.000000', NULL, 1),
(6081494, 894793, 114225, '<td valign="top">Wow, look at the muscles in this guy. I actually like how this is processed, for this shot (another shot processed this way probably wouldn''t look great).</td>', 'Wow, look at the muscles in this guy. I actually like how this is processed, for this shot (another shot processed this way probably wouldn''t look great).', '2010-07-05 20:15:17.000000', NULL, 1),
(6081495, 894572, 114225, '<td valign="top">Great details throughout the photo. I like the B&amp;W here (am I seeing some green in there too?).</td>', 'Great details throughout the photo. I like the B&W here (am I seeing some green in there too?).', '2010-07-05 20:16:13.000000', NULL, 1),
(6081496, 893252, 114225, '<td valign="top">Great use o leading lines and really cool colors.</td>', 'Great use o leading lines and really cool colors.', '2010-07-05 20:16:29.000000', NULL, 1),
(6081498, 894553, 114225, '<td valign="top">Good mood to this photo. The object on the ground is a little bit distracting, but overall a nice photo.</td>', 'Good mood to this photo. The object on the ground is a little bit distracting, but overall a nice photo.', '2010-07-05 20:17:06.000000', NULL, 1),
(6081499, 890635, 114225, '<td valign="top">Love the night colors here.</td>', 'Love the night colors here.', '2010-07-05 20:17:38.000000', NULL, 1),
(6081500, 893562, 40391, '<td valign="top">The colours are lovely and good timing to get the bee.  The shadows from the sun are a bit distracting. If you can''t position yourself to hide the shadows perhaps using a fill flash may have helped.  What really hurt this shot for me is the lack of focus. Macro shots really only work when the focus is sharp IMHO. I don''t have a macro lens so when I want to photo something small I back up enough to have the subject in focus then crop as much as possible without losing too much resolution.  3.</td>', 'The colours are lovely and good timing to get the bee.  The shadows from the sun are a bit distracting. If you can''t position yourself to hide the shadows perhaps using a fill flash may have helped.  What really hurt this shot for me is the lack of focus. Macro shots really only work when the focus is sharp IMHO. I don''t have a macro lens so when I want to photo something small I back up enough to have the subject in focus then crop as much as possible without losing too much resolution.  3.', '2010-07-05 20:18:04.000000', NULL, 1),
(6081501, 894807, 114225, '<td valign="top">This is a cool photo, much different than what you normally see.</td>', 'This is a cool photo, much different than what you normally see.', '2010-07-05 20:18:05.000000', NULL, 1),
(6081503, 894567, 114225, '<td valign="top">Wonderful colors. I love the details in the reeds close to the camera.</td>', 'Wonderful colors. I love the details in the reeds close to the camera.', '2010-07-05 20:18:27.000000', NULL, 1),
(6081505, 894753, 114225, '<td valign="top">Great shot, especially since other flowers seem to be pointed down while this one is gathering as much sun as it can.</td>', 'Great shot, especially since other flowers seem to be pointed down while this one is gathering as much sun as it can.', '2010-07-05 20:19:04.000000', NULL, 1),
(6081508, 894027, 40391, '<td valign="top">I like the colours but too many of the petals are over exposed and the focus is not quite there for me. 3.</td>', 'I like the colours but too many of the petals are over exposed and the focus is not quite there for me. 3.', '2010-07-05 20:19:52.000000', NULL, 1),
(6081509, 891645, 114225, '<td valign="top">I really like this scene. The red in the poppies seems slightly over saturated to me.</td>', 'I really like this scene. The red in the poppies seems slightly over saturated to me.', '2010-07-05 20:20:10.000000', NULL, 1),
(6081510, 893667, 114225, '<td valign="top">This is a really cool shot, I look forward to seeing how it''s done (my guess is a quick exposure for the sun, then lens cap on for a while before removing for the star trails).</td>', 'This is a really cool shot, I look forward to seeing how it''s done (my guess is a quick exposure for the sun, then lens cap on for a while before removing for the star trails).', '2010-07-05 20:20:54.000000', NULL, 1),
(6081511, 890545, 114225, '<td valign="top">Good use of HDR techniques to bring out the details in the rocks.</td>', 'Good use of HDR techniques to bring out the details in the rocks.', '2010-07-05 20:21:23.000000', NULL, 1),
(6081512, 894714, 114225, '<td valign="top">This is a very alluring shot. The background objects are a bit distracting, but also add some realism to the photo.</td>', 'This is a very alluring shot. The background objects are a bit distracting, but also add some realism to the photo.', '2010-07-05 20:22:05.000000', NULL, 1),
(6081513, 893509, 114225, '<td valign="top">Great photo. Perfect timing and nice silhouettes for the skyline.</td>', 'Great photo. Perfect timing and nice silhouettes for the skyline.', '2010-07-05 20:22:42.000000', NULL, 1),
(6081515, 894772, 114225, '<td valign="top">This is a nice photo, but I have some suggestions for improvement. There is a lot of noise (high iso?) which detracts from the image quite a bit. Also, in this case, I don''t think the fading border is adding anything to the photo, so I would have omitted it (but that''s completely personal taste).</td>', 'This is a nice photo, but I have some suggestions for improvement. There is a lot of noise (high iso?) which detracts from the image quite a bit. Also, in this case, I don''t think the fading border is adding anything to the photo, so I would have omitted it (but that''s completely personal taste).', '2010-07-05 20:24:03.000000', NULL, 1),
(6081518, 894780, 114225, '<td valign="top">Overall, a nice photo. Good lighting and personality. One small thing is what looks like a grocery store keycard by his right hand. Since that''s such a contrast to the black, it really sticks out. Maybe cloning it out would be good?</td>', 'Overall, a nice photo. Good lighting and personality. One small thing is what looks like a grocery store keycard by his right hand. Since that''s such a contrast to the black, it really sticks out. Maybe cloning it out would be good?', '2010-07-05 20:25:57.000000', NULL, 1),
(6081521, 888095, 114225, '<td valign="top">I like this. Certainly not something we see every day. It really tells a story as to what the local culture is like.</td>', 'I like this. Certainly not something we see every day. It really tells a story as to what the local culture is like.', '2010-07-05 20:26:56.000000', NULL, 1),
(6081522, 894222, 114225, '<td valign="top">This could have been a really cool photo if it has more sharpness. The soft feel can work in some photos, but this bird shot is calling for tack focus on the bird.</td>', 'This could have been a really cool photo if it has more sharpness. The soft feel can work in some photos, but this bird shot is calling for tack focus on the bird.', '2010-07-05 20:27:40.000000', NULL, 1),
(6081525, 894568, 114225, '<td valign="top">Great mood to this photo. Not only is he seemingly living in a box, but he''s super skinny looking.</td>', 'Great mood to this photo. Not only is he seemingly living in a box, but he''s super skinny looking.', '2010-07-05 20:28:29.000000', NULL, 1),
(6081526, 894586, 114225, '<td valign="top">This is a good area to photograph, but this photo doesn''t really draw me in. Maybe if my eyes were drawn along a river line, or the fountain was offset from center it would add a bit of interest for me.</td>', 'This is a good area to photograph, but this photo doesn''t really draw me in. Maybe if my eyes were drawn along a river line, or the fountain was offset from center it would add a bit of interest for me.', '2010-07-05 20:29:39.000000', NULL, 1),
(6081528, 894164, 114225, '<td valign="top">Fantastic photo! Great use of duo-tone and perfect composition.</td>', 'Fantastic photo! Great use of duo-tone and perfect composition.', '2010-07-05 20:32:25.000000', NULL, 1),
(6081530, 891183, 114225, '<td valign="top">Wonderful photo! Great interest from the front to the back. Did you use HDR techniques to bring out foreground details?</td>', 'Wonderful photo! Great interest from the front to the back. Did you use HDR techniques to bring out foreground details?', '2010-07-05 20:34:41.000000', NULL, 1),
(6081533, 894027, 114225, '<td valign="top">I''m sorry, I had to rate this one low due to focus. A shot like this calls for either pin point focus, or a lot of blurriness to create an abstract look. Unfortunately, this one falls somewhere in between.</td>', 'I''m sorry, I had to rate this one low due to focus. A shot like this calls for either pin point focus, or a lot of blurriness to create an abstract look. Unfortunately, this one falls somewhere in between.', '2010-07-05 20:36:17.000000', NULL, 1),
(6081534, 894547, 114225, '<td valign="top">Grat composition and perfect use of B&amp;W.</td>', 'Grat composition and perfect use of B&W.', '2010-07-05 20:37:32.000000', NULL, 1),
(6081535, 894784, 114225, '<td valign="top">This is an ok sunset photo, but it seems to lack real impact. Some things to look for in a great sunset photo include reflections, brilliant colors, large waves, or silhouettes in the distance (this is by no means a comprehensive list, just some things to look for).</td>', 'This is an ok sunset photo, but it seems to lack real impact. Some things to look for in a great sunset photo include reflections, brilliant colors, large waves, or silhouettes in the distance (this is by no means a comprehensive list, just some things to look for).', '2010-07-05 20:38:57.000000', NULL, 1),
