(6082944, 892927, 37845, '<td valign="top">I have seen the lion on the right in photos before, and he always looks at ease, despite the scars on his face. Great shot.</td>', 'I have seen the lion on the right in photos before, and he always looks at ease, despite the scars on his face. Great shot.', '2010-07-07 00:33:09.000000', NULL, 1),
(6082947, 894714, 37845, '<td valign="top">Beautiful shot, I like the warm tones.</td>', 'Beautiful shot, I like the warm tones.', '2010-07-07 00:33:50.000000', NULL, 1),
(6082948, 894697, 37845, '<td valign="top">This shot really gives a feeling of dense vegetation.</td>', 'This shot really gives a feeling of dense vegetation.', '2010-07-07 00:34:12.000000', NULL, 1),
(6082950, 893680, 37845, '<td valign="top">This is a stunning portrait. I think the fabric and the jewelery really add to the photo, and the softness on the skin is perfect. I think the processing in the eyes is a bit much though. Still, one of the best in the FS.</td>', 'This is a stunning portrait. I think the fabric and the jewelery really add to the photo, and the softness on the skin is perfect. I think the processing in the eyes is a bit much though. Still, one of the best in the FS.', '2010-07-07 00:35:31.000000', NULL, 1),
