INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6084092, 894799, 22392, '<td valign="top">You probably did the blur on purpose, but it looks too accidental to me</td>', 'You probably did the blur on purpose, but it looks too accidental to me', '2010-07-07 14:11:32.000000', NULL, 1),
(6084095, 892275, 22392, '<td valign="top">Nice use of the border, great picture</td>', 'Nice use of the border, great picture', '2010-07-07 14:15:31.000000', NULL, 1),
(6084114, 894339, 22392, '<td valign="top">I am sorry, but I hate Anne Geddes pictures, and this just looks too much like it. It´s well done, but I just get an allergic reaction to this type of pictures.</td>', 'I am sorry, but I hate Anne Geddes pictures, and this just looks too much like it. It´s well done, but I just get an allergic reaction to this type of pictures.', '2010-07-07 14:23:23.000000', NULL, 1),
(6084119, 894644, 22392, '<td valign="top">I would have made the border sepia-ish too instead of black. Apart from that a very nice picture (and a beautiful cat)</td>', 'I would have made the border sepia-ish too instead of black. Apart from that a very nice picture (and a beautiful cat)', '2010-07-07 14:27:08.000000', NULL, 1),
(6084123, 894777, 22392, '<td valign="top">awwwwwwww.... <br/> <br/>very nice details, you can almost feel the feathers</td>', 'awwwwwwww....  very nice details, you can almost feel the feathers', '2010-07-07 14:28:47.000000', NULL, 1),
(6084126, 894516, 22392, '<td valign="top">Extra point for title :) nice timing too on this shot.</td>', 'Extra point for title :) nice timing too on this shot.', '2010-07-07 14:29:18.000000', NULL, 1),
(6084140, 894339, 10523, '<td valign="top">wow- what a great shot- I hope it Ribbons</td>', 'wow- what a great shot- I hope it Ribbons', '2010-07-07 14:38:46.000000', NULL, 1),
(6084141, 893521, 10523, '<td valign="top">top 5 - beautiful shot</td>', 'top 5 - beautiful shot', '2010-07-07 14:38:59.000000', NULL, 1),
